    if (ev.titleFont && FONTS[ev.titleFont]) h1.style.fontFamily = FONTS[ev.titleFont];
    h1.style.fontWeight = ev.titleBold === false ? '400' : '700';
    var al = ev.titleAlign === 'center' || ev.titleAlign === 'right' ? ev.titleAlign : 'left';
    h1.style.textAlign = al; meta.style.textAlign = al;
    var kids = [h1, meta];
    if (ev.fee > 0) { var feeEl = el('span', { class: 'fee', text: 'Fee: \\u20B9' + ev.fee }); if (al === 'center') { kids.push(el('div', { style: 'text-align:center' }, [feeEl])); } else if (al === 'right') { kids.push(el('div', { style: 'text-align:right' }, [feeEl])); } else kids.push(feeEl); }
